import type { ExperienceMembership } from "./platform-model";

type FacilitiesView = "home" | "requests" | "new-request" | "spaces" | "warehouse" | "supplies" | "directory" | "reports" | "floor-plans" | "customize";
const stateKey = "navigate.facilities-demo.state.v1";
const navItems: Array<{ key: FacilitiesView; label: string; adminOnly?: boolean }> = [
  { key: "home", label: "Home" },
  { key: "requests", label: "Requests" },
  { key: "spaces", label: "Spaces" },
  { key: "supplies", label: "Office supplies" },
  { key: "warehouse", label: "Warehouse", adminOnly: true },
  { key: "directory", label: "Directory" },
  { key: "reports", label: "Reports", adminOnly: true },
  { key: "floor-plans", label: "Floor plans", adminOnly: true },
];

function loadState() {
  if (typeof window === "undefined") return cloneFacilitiesDemoState();
  try {
    const stored = window.localStorage.getItem(stateKey);
    return stored ? { ...cloneFacilitiesDemoState(), ...JSON.parse(stored) } as FacilitiesDemoState : cloneFacilitiesDemoState();
  } catch { return cloneFacilitiesDemoState(); }
}

function formatStatus(status: string) { return status.replaceAll("_", " "); }
function statusClass(status: string) { return status === "complete" || status === "approved" ? "confirmed" : status === "urgent" || status === "declined" ? "declined" : "pending"; }
function nextId(prefix: string, existing: Array<{ id: string }>, fallback: number) {
  return Math.max(fallback, ...existing.map((item) => Number(item.id.replace(/\D/g, "")) || 0)) + 1;
}

function FacilitiesIcon({ name }: { name: string }) {
  const paths: Record<string, string> = {
    home: "M3 11.5 12 4l9 7.5M5.5 10v10h13V10M9 20v-6h6v6",
    requests: "M6 3h12v18H6zM9 8h6M9 12h6M9 16h4",
    spaces: "M4 5h16v14H4zM8 5v14M8 10h12M14 10v9",
    supplies: "M4 8h16v12H4zM7 8V5h10v3M9 12h6",
    warehouse: "M3 9l9-5 9 5v11H3zM7 13h10M7 17h10M8 9h8",
    directory: "M8 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8Zm-6 9a6 6 0 0 1 12 0M17 9h5M17 13h5M17 17h4",
    reports: "M5 20V10h3v10M11 20V4h3v16M17 20v-7h3v7M3 20h19",
    "floor-plans": "M3 5l6-2 6 2 6-2v16l-6 2-6-2-6 2zM9 3v16M15 5v16",
  };
  return <svg viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round"><path d={paths[name] || paths.home} /></svg>;
}

function FacilitiesHeader({ api, memberships, context, previewMode, signOut }: { api: PilotApiClient; memberships: ExperienceMembership[]; context: AuthorizationContext; previewMode: boolean; signOut: () => Promise<void> }) {
  return <header className="facilities-header">
    <a className="facilities-parent-brand" href="/app/compass" aria-label="Compass home"><img src="/assets/brand/compass-emblem-v2.png" alt="" /><span>Compass</span></a>
    <div className="facilities-title"><span className="facilities-title__mark" aria-hidden="true">F</span><span><small>Campus operations</small><strong>Facilities Dashboard</strong></span></div>
    <WorkspaceSwitcher api={api} memberships={memberships} current="facilities" previewMode={previewMode} />
    <div className="facilities-account"><span>{context.displayName}</span><button className="text-button" type="button" onClick={() => void signOut()}>Leave demo</button></div>
  </header>;
}

function FacilitiesRoleChooser({ persona, onPersona, signOut }: { persona: SyntheticPersonaKey; onPersona: (persona: SyntheticPersonaKey) => void; signOut: () => Promise<void> }) {
  const choose = (next: SyntheticPersonaKey) => {
    const url = new URL(window.location.href);
    url.searchParams.set("preview", "facilities");
    url.searchParams.set("demo", facilitiesDemoSlugForPersona(next));
    window.history.replaceState({}, "", `${url.pathname}${url.search}`);
    if (next === persona) window.location.replace(`${url.pathname}${url.search}`);
    else onPersona(next);
  };
  return <div className="navigate-platform facilities-shell">
    <CreatorPreviewBanner persona={persona} onPersona={onPersona} onExit={() => void signOut()} scope="facilities" tutorialWorkspace="facilities" />
    <main className="facilities-demo-entry">
      <section className="facilities-role-chooser" aria-labelledby="facilities-role-title">
        <div className="facilities-role-chooser__brand"><img src="/assets/brand/compass-emblem-v2.png" alt="" /><span>Compass</span></div>
        <p className="kicker">Facilities demonstration</p>
        <h1 id="facilities-role-title">Choose a view.</h1>
        <p>Explore one connected, fictional workflow from the person making a request or the Facilities team coordinating the response.</p>
        <div className="facilities-role-grid">{FACILITIES_DEMO_PERSONAS.map((item) => <button key={item.key} type="button" onClick={() => choose(item.key)}><span aria-hidden="true"><FacilitiesIcon name={item.key === "facilities_administrator" ? "reports" : "requests"} /></span><strong>{item.label}</strong><small>{item.description}</small><i>Open view</i></button>)}</div>
        <small>No sign-in or access code is required. All names and records in this demo are fictional.</small>
      </section>
    </main>
  </div>;
}

function Metrics({ state }: { state: FacilitiesDemoState }) {
  const pending = state.requests.filter((item) => item.status === "approval").length + state.reservations.filter((item) => item.status === "pending").length;
  const active = state.requests.filter((item) => ["prep", "in_progress"].includes(item.status)).length;
  const low = state.stock.filter((item) => item.onHand <= item.reorderPoint).length;
  const today = state.reservations.filter((item) => item.date === "2026-09-15" && item.status === "approved").length;
  return <div className="facilities-metrics" aria-label="Facilities summary"><article><span>Needs approval</span><strong>{pending}</strong><small>requests and spaces</small></article><article><span>Active work</span><strong>{active}</strong><small>prep or in progress</small></article><article><span>Low stock</span><strong>{low}</strong><small>at reorder level</small></article><article><span>Rooms today</span><strong>{today}</strong><small>approved reservations</small></article></div>;
}

function InsightPanel({ state, onNavigate }: { state: FacilitiesDemoState; onNavigate: (view: FacilitiesView) => void }) {
  return <section className="facilities-panel facilities-priority-panel" data-tutorial-id="facilities-priorities"><header><div><p className="kicker">Smart priorities</p><h2>What needs attention next</h2></div><span className="facilities-rule-chip">Explainable rules</span></header><div className="facilities-insight-list">{facilitiesInsights(state).map((item) => <article key={item.id} className={`facilities-insight facilities-insight--${item.level}`}><span aria-hidden="true" /><div><strong>{item.title}</strong><p>{item.detail}</p><details><summary>Why this appears</summary><p>{item.source}</p></details></div><button type="button" className="text-button" onClick={() => onNavigate(item.id === "low-stock" || item.id === "overstock" || item.id === "chair-use" ? "warehouse" : item.id === "liquor" ? "spaces" : "requests")}>Review</button></article>)}</div></section>;
}

function WorkflowBoard({ state, onOpen }: { state: FacilitiesDemoState; onOpen: (request: FacilitiesRequest) => void }) {
  return <section className="facilities-panel facilities-workflow-panel" data-tutorial-id="facilities-workflow"><header><div><p className="kicker">Live work</p><h2>Request → approval → preparation → work</h2></div><span>{state.requests.filter((item) => item.status !== "complete").length} open</span></header><div className="facilities-kanban">{facilitiesRequestStages.slice(0, 4).map((stage) => <div key={stage.key} className="facilities-kanban__column"><h3><span>{stage.label}</span><b>{state.requests.filter((item) => item.status === stage.key).length}</b></h3>{state.requests.filter((item) => item.status === stage.key).map((item) => <button key={item.id} type="button" onClick={() => onOpen(item)}><small>{item.id} · {item.location}</small><strong>{item.title}</strong><span className={`status-chip status-chip--${statusClass(item.priority)}`}>{item.priority}</span></button>)}</div>)}</div></section>;
}

function UsagePanel({ state }: { state: FacilitiesDemoState }) {
  const items = [...state.stock].sort((a, b) => b.averageWeeklyUse - a.averageWeeklyUse).slice(0, 5);
  const max = Math.max(...items.map((item) => item.averageWeeklyUse), 1);
  return <section className="facilities-panel facilities-usage-panel"><header><div><p className="kicker">Demand pattern</p><h2>Typical weekly movement</h2></div><span>Last 8 weeks</span></header><div className="facilities-bar-chart">{items.map((item) => <div key={item.id}><span>{item.name}</span><div><i style={{ width: `${Math.round(item.averageWeeklyUse / max * 100)}%` }} /></div><strong>{item.averageWeeklyUse}</strong></div>)}</div><p className="facilities-chart-note">Use patterns help set reorder points and flag unusual demand. They do not automatically place orders.</p></section>;
}

function AdminHome({ state, onNavigate, onOpen }: { state: FacilitiesDemoState; onNavigate: (view: FacilitiesView) => void; onOpen: (request: FacilitiesRequest) => void }) {
  const visible = (key: string) => state.dashboardSections.includes(key) && !state.hiddenDashboardSections.includes(key);
  return <div className="facilities-page"><div className="facilities-page-heading"><div><p className="kicker">Tuesday, September 15</p><h1>Good morning, Alex.</h1><p>Start with today’s approvals, preparations, and resource signals.</p></div><div><button className="secondary-button" type="button" onClick={() => onNavigate("customize")}>Customize dashboard</button><button className="primary-button" type="button" onClick={() => onNavigate("new-request")}>New request</button></div></div><Metrics state={state} />{visible("priorities") ? <InsightPanel state={state} onNavigate={onNavigate} /> : null}{visible("workflow") ? <WorkflowBoard state={state} onOpen={onOpen} /> : null}<div className="facilities-two-column">{visible("usage") ? <UsagePanel state={state} /> : null}{visible("activity") ? <section className="facilities-panel"><header><div><p className="kicker">Activity</p><h2>Recently updated</h2></div></header><div className="facilities-timeline">{state.activity.map((item) => <article key={item.id}><span /><div><strong>{item.text}</strong><small>{new Date(item.at).toLocaleString()}</small></div></article>)}</div></section> : null}</div></div>;
}

function RequesterHome({ state, onNavigate, onOpen, requester }: { state: FacilitiesDemoState; onNavigate: (view: FacilitiesView) => void; onOpen: (request: FacilitiesRequest) => void; requester: string }) {
  const mine = state.requests.filter((item) => item.requester === requester || item.department === "Student Affairs");
  return <div className="facilities-page" data-tutorial-id="facilities-requester-home"><div className="facilities-page-heading facilities-requester-welcome"><div><p className="kicker">Facilities requests</p><h1>What can we help with?</h1><p>Send the request once, then follow its approval, preparation, and Facilities updates here.</p></div><button className="primary-button" type="button" onClick={() => onNavigate("new-request")}>Start a request</button></div><div className="facilities-requester-actions"><button onClick={() => onNavigate("new-request")}><FacilitiesIcon name="requests" /><strong>Report a problem</strong><span>Repairs, maintenance, moves</span></button><button onClick={() => onNavigate("spaces")}><FacilitiesIcon name="spaces" /><strong>Reserve a space</strong><span>Rooms, events, setup</span></button><button onClick={() => onNavigate("supplies")}><FacilitiesIcon name="supplies" /><strong>Request supplies</strong><span>Office and department needs</span></button></div><section className="facilities-panel" data-tutorial-id="facilities-my-requests"><header><div><p className="kicker">My activity</p><h2>Requests in progress</h2></div><button className="text-button" onClick={() => onNavigate("requests")}>View all</button></header><div className="facilities-request-list">{mine.filter((item) => item.status !== "complete").map((item) => <button type="button" key={item.id} onClick={() => onOpen(item)}><span className={`facilities-request-icon facilities-request-icon--${item.category}`}><FacilitiesIcon name={item.category === "office_supplies" ? "supplies" : "requests"} /></span><span><small>{item.id} · {item.location}</small><strong>{item.title}</strong><em>Needed {new Date(`${item.requestedFor}T12:00:00`).toLocaleDateString()}</em></span><span className={`status-chip status-chip--${statusClass(item.status)}`}>{formatStatus(item.status)}</span></button>)}</div></section></div>;
}

function RequestForm({ state, setState, requester, defaultCategory = "work_order", onDone }: { state: FacilitiesDemoState; setState: React.Dispatch<React.SetStateAction<FacilitiesDemoState>>; requester: string; defaultCategory?: FacilitiesRequest["category"]; onDone: (request: FacilitiesRequest) => void }) {
  const [category, setCategory] = useState<FacilitiesRequest["category"]>(defaultCategory);
  const [title, setTitle] = useState(""); const [department, setDepartment] = useState("Student Affairs"); const [location, setLocation] = useState(""); const [priority, setPriority] = useState<FacilitiesRequest["priority"]>("routine"); const [requestedFor, setRequestedFor] = useState("2026-09-18"); const [description, setDescription] = useState(""); const [message, setMessage] = useState("");
  const submit = (event: React.FormEvent) => {
    event.preventDefault();
    const id = `WO-${nextId("WO", state.requests, 1048)}`;
    const request: FacilitiesRequest = { id, title, category, requester, department, location, priority, status: "new_request", description, requestedFor, assignedTo: null, prepTasks: [], parts: [], reservationId: null, createdAt: new Date().toISOString(), updatedAt: new Date().toISOString(), messages: [] };
    setState((current) => ({ ...current, requests: [request, ...current.requests], activity: [{ id: `activity-${Date.now()}`, text: `${id} submitted by ${requester}`, at: new Date().toISOString() }, ...current.activity] }));
    setMessage(`${id} was submitted to Facilities.`); window.setTimeout(() => onDone(request), 350);
  };
  return <form className="facilities-panel facilities-request-form" data-tutorial-id="facilities-new-request" onSubmit={submit}><header><div><p className="kicker">New request</p><h1>Tell Facilities what you need.</h1><p>Required details are kept short. You can add files and messages after submission.</p></div></header><div className="facilities-form-grid"><label><span>Request type</span><select value={category} onChange={(event) => setCategory(event.target.value as FacilitiesRequest["category"])}><option value="work_order">Work order</option><option value="office_supplies">Office supplies</option><option value="event_setup">Event preparation</option></select></label><label><span>Department</span><select value={department} onChange={(event) => setDepartment(event.target.value)}><option>Student Affairs</option><option>College of Medicine</option><option>Academic Affairs</option><option>Admissions</option><option>University Advancement</option></select></label><label className="facilities-field-wide"><span>Short title</span><input required value={title} onChange={(event) => setTitle(event.target.value)} placeholder="Example: Replace damaged chair" /></label><label><span>Location</span><input required value={location} onChange={(event) => setLocation(event.target.value)} placeholder="Building, room, or area" /></label><label><span>Needed by</span><input required type="date" value={requestedFor} onChange={(event) => setRequestedFor(event.target.value)} /></label><label><span>Priority</span><select value={priority} onChange={(event) => setPriority(event.target.value as FacilitiesRequest["priority"])}><option value="routine">Routine</option><option value="soon">Soon</option><option value="urgent">Urgent — safety or active disruption</option></select></label><label className="facilities-field-wide"><span>Details</span><textarea required rows={5} value={description} onChange={(event) => setDescription(event.target.value)} placeholder="What is happening, what outcome is needed, and when is the space available?" /></label></div><div className="facilities-form-actions"><button className="primary-button">Submit request</button><span aria-live="polite">{message}</span></div></form>;
}

function RequestDetail({ request, state, setState, admin, onBack }: { request: FacilitiesRequest; state: FacilitiesDemoState; setState: React.Dispatch<React.SetStateAction<FacilitiesDemoState>>; admin: boolean; onBack: () => void }) {
  const current = state.requests.find((item) => item.id === request.id) || request;
  const [update, setUpdate] = useState("");
  const patchRequest = (patch: Partial<FacilitiesRequest>, activity?: string) => setState((value) => ({ ...value, requests: value.requests.map((item) => item.id === current.id ? { ...item, ...patch, updatedAt: new Date().toISOString() } : item), activity: activity ? [{ id: `activity-${Date.now()}`, text: activity, at: new Date().toISOString() }, ...value.activity] : value.activity }));
  const advance = () => { const next = nextFacilitiesRequestStatus(current.status); if (next) patchRequest({ status: next }, `${current.id} moved to ${formatStatus(next)}`); };
  const send = () => { if (!update.trim()) return; patchRequest({ messages: [...current.messages, { id: `msg-${Date.now()}`, channel: "email", body: update.trim(), sentAt: new Date().toISOString(), sender: admin ? "Alex Rivera" : current.requester }] }, `${current.id} communication added`); setUpdate(""); };
  return <section className="facilities-page"><button className="workspace-back text-button" onClick={onBack}>← All requests</button><div className="facilities-detail-heading"><div><small>{current.id} · {current.category.replaceAll("_", " ")}</small><h1>{current.title}</h1><p>{current.location} · Needed {new Date(`${current.requestedFor}T12:00:00`).toLocaleDateString()}</p></div><span className={`status-chip status-chip--${statusClass(current.status)}`}>{formatStatus(current.status)}</span></div><div className="facilities-two-column facilities-detail-grid"><div><section className="facilities-panel"><header><div><p className="kicker">Request</p><h2>Details</h2></div></header><dl className="facilities-detail-list"><div><dt>Requester</dt><dd>{current.requester}</dd></div><div><dt>Department</dt><dd>{current.department}</dd></div><div><dt>Priority</dt><dd>{current.priority}</dd></div><div><dt>Assigned to</dt><dd>{current.assignedTo || "Not assigned"}</dd></div></dl><p>{current.description}</p>{current.reservationId ? <p className="facilities-linked-record">Linked reservation: <strong>{current.reservationId}</strong></p> : null}{admin ? <div className="facilities-admin-actions"><label><span>Assigned staff</span><select value={current.assignedTo || ""} onChange={(event) => patchRequest({ assignedTo: event.target.value || null })}><option value="">Not assigned</option><option>Alex Rivera</option><option>Jordan Kim</option><option>Sam Patel</option></select></label>{nextFacilitiesRequestStatus(current.status) ? <button className="primary-button" onClick={advance}>{current.status === "approval" ? "Approve and begin prep" : `Move to ${formatStatus(nextFacilitiesRequestStatus(current.status)!)}`}</button> : null}</div> : null}</section><section className="facilities-panel"><header><div><p className="kicker">Preparation</p><h2>Checklist and parts</h2></div></header>{current.prepTasks.length ? <div className="facilities-checklist">{current.prepTasks.map((task) => <label key={task.id}><input type="checkbox" disabled={!admin} checked={task.complete} onChange={(event) => patchRequest({ prepTasks: current.prepTasks.map((item) => item.id === task.id ? { ...item, complete: event.target.checked } : item) })} /><span>{task.label}</span></label>)}</div> : <p>No preparation checklist has been added yet.</p>}<div className="facilities-parts">{current.parts.map((part) => <span key={part.itemId}>{part.quantity} × {part.name}</span>)}{!current.parts.length ? <small>No stock reserved.</small> : null}</div>{admin ? <button className="secondary-button" onClick={() => patchRequest({ prepTasks: [...current.prepTasks, { id: `task-${Date.now()}`, label: "Confirm final preparation with requester", complete: false }] })}>Add preparation step</button> : null}</section></div><section className="facilities-panel facilities-conversation"><header><div><p className="kicker">Updates</p><h2>Request conversation</h2></div></header>{current.messages.map((item) => <article key={item.id}><strong>{item.sender}</strong><small>{item.channel === "email" ? "Email + in-platform" : "In-platform"} · {new Date(item.sentAt).toLocaleString()}</small><p>{item.body}</p></article>)}{!current.messages.length ? <p>No updates yet.</p> : null}<label><span>Send an update</span><textarea rows={4} value={update} onChange={(event) => setUpdate(event.target.value)} /></label><button className="primary-button" disabled={!update.trim()} onClick={send}>Send update</button><small>Demo only: external email is simulated and no message leaves this browser.</small></section></div></section>;
}

function RequestsView({ state, setState, admin, requester, onOpen, onNew }: { state: FacilitiesDemoState; setState: React.Dispatch<React.SetStateAction<FacilitiesDemoState>>; admin: boolean; requester: string; onOpen: (request: FacilitiesRequest) => void; onNew: () => void }) {
  const [filter, setFilter] = useState<FacilitiesRequestStatus | "all">("all");
  const visible = state.requests.filter((item) => (admin || item.requester === requester || item.department === "Student Affairs") && (filter === "all" || item.status === filter));
  return <section className="facilities-page"><div className="facilities-page-heading"><div><p className="kicker">Requests</p><h1>{admin ? "Coordinate every request in one flow." : "Track your requests."}</h1><p>{admin ? "Approval, preparation, assigned work, parts, and communication stay on the same record." : "See exactly where each request is and read Facilities updates."}</p></div><button className="primary-button" onClick={onNew}>New request</button></div><div className="facilities-filter-row"><button className={filter === "all" ? "active" : ""} onClick={() => setFilter("all")}>All <span>{visible.length}</span></button>{facilitiesRequestStages.map((stage) => <button key={stage.key} className={filter === stage.key ? "active" : ""} onClick={() => setFilter(stage.key)}>{stage.label} <span>{state.requests.filter((item) => (admin || item.requester === requester || item.department === "Student Affairs") && item.status === stage.key).length}</span></button>)}</div><div className="facilities-table-wrap"><table className="facilities-table"><thead><tr><th>Request</th><th>Location</th><th>Needed</th><th>Owner</th><th>Status</th></tr></thead><tbody>{visible.map((item) => <tr key={item.id} onClick={() => onOpen(item)}><td><button type="button"><small>{item.id}</small><strong>{item.title}</strong></button></td><td>{item.location}</td><td>{new Date(`${item.requestedFor}T12:00:00`).toLocaleDateString()}</td><td>{item.assignedTo || "Unassigned"}</td><td><span className={`status-chip status-chip--${statusClass(item.status)}`}>{formatStatus(item.status)}</span></td></tr>)}</tbody></table></div></section>;
}

function SpacesView({ state, setState, admin, requester }: { state: FacilitiesDemoState; setState: React.Dispatch<React.SetStateAction<FacilitiesDemoState>>; admin: boolean; requester: string }) {
  const [formOpen, setFormOpen] = useState(false); const [title, setTitle] = useState(""); const [organization, setOrganization] = useState("Student Affairs"); const [roomId, setRoomId] = useState(facilitiesRooms[0].id); const [date, setDate] = useState("2026-09-22"); const [startsAt, setStartsAt] = useState("10:00"); const [endsAt, setEndsAt] = useState("11:00"); const [eventType, setEventType] = useState("Meeting"); const [attendees, setAttendees] = useState(10); const [alcohol, setAlcohol] = useState(false); const [setupNotes, setSetupNotes] = useState(""); const [message, setMessage] = useState("");
  const visible = (admin ? state.reservations : state.reservations.filter((item) => item.requestedBy === requester || item.organization === "Student Affairs")).slice();
  const submit = (event: React.FormEvent) => { event.preventDefault(); const room = facilitiesRooms.find((item) => item.id === roomId)!; const candidate: FacilitiesReservation = { id: `RSV-${nextId("RSV", state.reservations, 2206)}`, title, organization, roomId, roomName: room.name, date, startsAt, endsAt, eventType, attendees, alcohol, liquorLicenseStatus: alcohol ? "needed" : "not_required", status: "pending", requestedBy: requester, setupNotes, linkedRequestId: null }; const conflicts = reservationConflicts(candidate, state.reservations); if (conflicts.length) { setMessage(`${room.name} conflicts with ${conflicts[0].title} from ${conflicts[0].startsAt} to ${conflicts[0].endsAt}.`); return; } setState((current) => ({ ...current, reservations: [candidate, ...current.reservations] })); setMessage(`${candidate.id} was sent to Facilities for approval.`); setFormOpen(false); };
  const approve = (reservation: FacilitiesReservation) => { if (reservation.alcohol && reservation.liquorLicenseStatus !== "received") { setMessage("Mark the liquor license received before approving this reservation."); return; } const request = makeEventSetupRequest({ ...reservation, status: "approved" }, nextId("WO", state.requests, 1048)); setState((current) => ({ ...current, reservations: current.reservations.map((item) => item.id === reservation.id ? { ...item, status: "approved", linkedRequestId: request.id } : item), requests: [request, ...current.requests], activity: [{ id: `activity-${Date.now()}`, text: `${reservation.id} approved; ${request.id} created for preparation`, at: new Date().toISOString() }, ...current.activity] })); setMessage(`${reservation.id} approved and ${request.id} created in Prep.`); };
  return <section className="facilities-page" data-tutorial-id="facilities-spaces"><div className="facilities-page-heading"><div><p className="kicker">Space reservations</p><h1>Rooms and preparation, together.</h1><p>Check availability, approve the space, and create its preparation work without re-entering details.</p></div><button className="primary-button" onClick={() => setFormOpen((value) => !value)}>{formOpen ? "Close form" : "Reserve a space"}</button></div>{formOpen ? <form className="facilities-panel facilities-request-form" onSubmit={submit}><header><div><h2>New space request</h2><p>The Facilities calendar is authoritative in this demo.</p></div></header><div className="facilities-form-grid"><label className="facilities-field-wide"><span>Event or meeting</span><input required value={title} onChange={(event) => setTitle(event.target.value)} /></label><label><span>Organization</span><select value={organization} onChange={(event) => setOrganization(event.target.value)}><option>Student Affairs</option><option>College of Medicine</option><option>Academic Affairs</option><option>Student Council</option><option>University Advancement</option></select></label><label><span>Event type</span><select value={eventType} onChange={(event) => setEventType(event.target.value)}><option>Meeting</option><option>Reception</option><option>Student organization</option><option>Training</option><option>Community event</option></select></label><label><span>Room</span><select value={roomId} onChange={(event) => setRoomId(event.target.value)}>{facilitiesRooms.filter((room) => ["Conference room", "Meeting room", "Event space", "Classroom"].includes(room.type)).map((room) => <option key={room.id} value={room.id}>{room.name} · {room.capacity}</option>)}</select></label><label><span>Date</span><input type="date" value={date} onChange={(event) => setDate(event.target.value)} /></label><label><span>Starts</span><input type="time" value={startsAt} onChange={(event) => setStartsAt(event.target.value)} /></label><label><span>Ends</span><input type="time" value={endsAt} onChange={(event) => setEndsAt(event.target.value)} /></label><label><span>Expected attendance</span><input type="number" min="1" value={attendees} onChange={(event) => setAttendees(Number(event.target.value))} /></label><label className="facilities-check-row"><input type="checkbox" checked={alcohol} onChange={(event) => setAlcohol(event.target.checked)} /><span>Alcohol will be served</span></label><label className="facilities-field-wide"><span>Setup and accessibility needs</span><textarea rows={4} value={setupNotes} onChange={(event) => setSetupNotes(event.target.value)} /></label></div><button className="primary-button">Submit space request</button></form> : null}<p className="form-message" aria-live="polite">{message}</p><div className="facilities-reservation-grid">{visible.sort((a, b) => `${a.date}${a.startsAt}`.localeCompare(`${b.date}${b.startsAt}`)).map((item) => <article key={item.id}><div className="facilities-date-block"><strong>{new Date(`${item.date}T12:00:00`).toLocaleDateString(undefined, { month: "short" })}</strong><span>{new Date(`${item.date}T12:00:00`).getDate()}</span></div><div><small>{item.id} · {item.eventType}</small><h2>{item.title}</h2><p>{item.roomName} · {item.startsAt}–{item.endsAt} · {item.attendees} people</p><p>{item.organization}</p>{item.alcohol ? <span className={`facilities-license facilities-license--${item.liquorLicenseStatus}`}>Liquor license: {formatStatus(item.liquorLicenseStatus)}</span> : null}{item.linkedRequestId ? <p className="facilities-linked-record">Preparation: <strong>{item.linkedRequestId}</strong></p> : null}</div><div className="facilities-reservation-actions"><span className={`status-chip status-chip--${statusClass(item.status)}`}>{item.status}</span>{admin && item.alcohol && item.liquorLicenseStatus === "needed" ? <button className="secondary-button" onClick={() => setState((current) => ({ ...current, reservations: current.reservations.map((reservation) => reservation.id === item.id ? { ...reservation, liquorLicenseStatus: "received" } : reservation) }))}>Mark license received</button> : null}{admin && item.status === "pending" ? <button className="primary-button" onClick={() => approve(item)}>Approve + create prep</button> : null}</div></article>)}</div></section>;
}

function WarehouseView({ state, setState }: { state: FacilitiesDemoState; setState: React.Dispatch<React.SetStateAction<FacilitiesDemoState>> }) {
  const [createOpen, setCreateOpen] = useState(false); const [name, setName] = useState(""); const [sku, setSku] = useState(""); const [category, setCategory] = useState("Office supplies"); const [onHand, setOnHand] = useState(0); const [message, setMessage] = useState("");
  const adjust = (id: string, change: number) => setState((current) => ({ ...current, stock: current.stock.map((item) => item.id === id ? { ...item, onHand: Math.max(0, item.onHand + change), lastCounted: "2026-09-15" } : item) }));
  const create = (event: React.FormEvent) => { event.preventDefault(); const item: FacilitiesStockItem = { id: `stock-${Date.now()}`, sku, name, category, onHand, reorderPoint: Math.max(1, Math.round(onHand * .25)), target: Math.max(onHand, Math.round(onHand * 1.5)), unit: "each", location: "Warehouse B", averageWeeklyUse: 0, lastCounted: "2026-09-15" }; setState((current) => ({ ...current, stock: [item, ...current.stock] })); setCreateOpen(false); setMessage(`${name} was added to inventory.`); };
  const checkIn = (id: string) => setState((current) => ({ ...current, custody: current.custody.filter((item) => item.id !== id) }));
  return <section className="facilities-page" data-tutorial-id="facilities-warehouse"><div className="facilities-page-heading"><div><p className="kicker">Warehouse</p><h1>Know what is available—and where it went.</h1><p>Quantity-based stock supports purchasing. Lightweight custody records answer who is using durable furniture and equipment.</p></div><button className="primary-button" onClick={() => setCreateOpen((value) => !value)}>Create an item</button></div>{createOpen ? <form className="facilities-panel facilities-inline-form" onSubmit={create}><label><span>Item name</span><input required value={name} onChange={(event) => setName(event.target.value)} /></label><label><span>SKU</span><input required value={sku} onChange={(event) => setSku(event.target.value)} /></label><label><span>Category</span><select value={category} onChange={(event) => setCategory(event.target.value)}><option>Office supplies</option><option>Furniture</option><option>Maintenance</option><option>Event equipment</option></select></label><label><span>Starting quantity</span><input type="number" min="0" value={onHand} onChange={(event) => setOnHand(Number(event.target.value))} /></label><button className="primary-button">Add item</button></form> : null}<p className="form-message" aria-live="polite">{message}</p><section className="facilities-panel"><header><div><p className="kicker">Stock</p><h2>On-hand inventory</h2></div><span>{state.stock.length} items</span></header><div className="facilities-table-wrap"><table className="facilities-table facilities-stock-table"><thead><tr><th>Item</th><th>Location</th><th>On hand</th><th>Reorder</th><th>Typical use</th><th>Count</th></tr></thead><tbody>{state.stock.map((item) => <tr key={item.id}><td><small>{item.sku}</small><strong>{item.name}</strong></td><td>{item.location}</td><td><b className={item.onHand <= item.reorderPoint ? "facilities-low-stock" : ""}>{item.onHand} {item.unit}</b></td><td>{item.reorderPoint}</td><td>{item.averageWeeklyUse}/week</td><td><div className="facilities-count-stepper"><button aria-label={`Remove one ${item.name}`} onClick={() => adjust(item.id, -1)}>−</button><span>{item.onHand}</span><button aria-label={`Add one ${item.name}`} onClick={() => adjust(item.id, 1)}>+</button></div></td></tr>)}</tbody></table></div></section><section className="facilities-panel"><header><div><p className="kicker">Checked out</p><h2>Durable-item custody</h2></div><button className="secondary-button" onClick={() => setState((current) => ({ ...current, custody: [{ id: `CST-${Date.now()}`, itemName: "Portable presentation kit", quantity: 1, holder: "Academic Affairs", holderType: "department", checkedOutAt: new Date().toISOString(), dueAt: "2026-09-22T17:00:00-07:00", condition: "good" }, ...current.custody] }))}>Check out an item</button></header><div className="facilities-custody-grid">{state.custody.map((item) => <article key={item.id}><span className={`status-chip status-chip--${item.condition === "needs_attention" ? "declined" : "pending"}`}>{formatStatus(item.condition)}</span><strong>{item.quantity} × {item.itemName}</strong><p>With {item.holder} · {item.holderType}</p><small>Out {new Date(item.checkedOutAt).toLocaleDateString()}{item.dueAt ? ` · Due ${new Date(item.dueAt).toLocaleDateString()}` : " · Ongoing assignment"}</small><button className="text-button" onClick={() => checkIn(item.id)}>Check in</button></article>)}</div></section></section>;
}

function SuppliesView({ state, setState, admin, requester, onOpen }: { state: FacilitiesDemoState; setState: React.Dispatch<React.SetStateAction<FacilitiesDemoState>>; admin: boolean; requester: string; onOpen: (request: FacilitiesRequest) => void }) {
  const [itemId, setItemId] = useState("stock-paper"); const [quantity, setQuantity] = useState(1); const [message, setMessage] = useState("");
  const submit = (event: React.FormEvent) => { event.preventDefault(); const item = state.stock.find((record) => record.id === itemId)!; const id = `WO-${nextId("WO", state.requests, 1048)}`; const request: FacilitiesRequest = { id, title: `Deliver ${item.name}`, category: "office_supplies", requester, department: "Student Affairs", location: "Student Affairs Suite", priority: "routine", status: "new_request", description: `${quantity} ${item.unit}${quantity === 1 ? "" : "s"} requested through internal supplies.`, requestedFor: "2026-09-18", assignedTo: null, prepTasks: [], parts: [{ itemId, name: item.name, quantity }], reservationId: null, createdAt: new Date().toISOString(), updatedAt: new Date().toISOString(), messages: [] }; setState((current) => ({ ...current, requests: [request, ...current.requests] })); setMessage(`${id} was submitted.`); };
  const supplies = state.requests.filter((item) => item.category === "office_supplies" && (admin || item.requester === requester || item.department === "Student Affairs"));
  return <section className="facilities-page"><div className="facilities-page-heading"><div><p className="kicker">Internal departments</p><h1>Office supply requests</h1><p>Request available stock and follow delivery without a separate email chain.</p></div></div><div className="facilities-two-column"><form className="facilities-panel facilities-supply-form" onSubmit={submit}><h2>Request supplies</h2><label><span>Item</span><select value={itemId} onChange={(event) => setItemId(event.target.value)}>{state.stock.filter((item) => item.category === "Office supplies").map((item) => <option key={item.id} value={item.id}>{item.name} · {item.onHand} available</option>)}</select></label><label><span>Quantity</span><input type="number" min="1" value={quantity} onChange={(event) => setQuantity(Number(event.target.value))} /></label><button className="primary-button">Submit supply request</button><p className="form-message" aria-live="polite">{message}</p></form><section className="facilities-panel"><header><div><p className="kicker">Delivery queue</p><h2>{supplies.length} supply requests</h2></div></header><div className="facilities-mini-list">{supplies.map((item) => <button key={item.id} onClick={() => onOpen(item)}><span><small>{item.id}</small><strong>{item.title}</strong><em>{item.department}</em></span><span className={`status-chip status-chip--${statusClass(item.status)}`}>{formatStatus(item.status)}</span></button>)}</div></section></div></section>;
}

function DirectoryView() {
  const [search, setSearch] = useState(""); const filtered = facilitiesDirectory.filter((item) => `${item.name} ${item.role} ${item.group}`.toLowerCase().includes(search.toLowerCase()));
  return <section className="facilities-page"><div className="facilities-page-heading"><div><p className="kicker">Contacts</p><h1>Facilities directory</h1><p>Find the right internal contact without leaving the request workspace.</p></div><label className="facilities-search"><span className="sr-only">Search directory</span><input value={search} onChange={(event) => setSearch(event.target.value)} placeholder="Search people or teams" /></label></div><div className="facilities-directory-grid">{filtered.map((item) => <article key={item.id}><span>{item.name.split(" ").map((part) => part[0]).join("").slice(0, 2)}</span><div><strong>{item.name}</strong><p>{item.role} · {item.group}</p><a href={`mailto:${item.email}`}>{item.email}</a><a href={`tel:${item.phone}`}>{item.phone}</a></div></article>)}</div></section>;
}

function FloorPlanView({ state }: { state: FacilitiesDemoState }) {
  const [selectedId, setSelectedId] = useState(facilitiesRooms[0].id); const room = facilitiesRooms.find((item) => item.id === selectedId)!; const work = state.requests.filter((item) => item.location.toLowerCase().includes(room.name.toLowerCase().replace("conference room ", "")) || item.location === room.name); const reservations = state.reservations.filter((item) => item.roomId === room.id && item.status !== "cancelled");
  return <section className="facilities-page" data-tutorial-id="facilities-floor-plan"><div className="facilities-page-heading"><div><p className="kicker">Floor plans</p><h1>See operations by place.</h1><p>This schematic demo plan contains no real building-security detail.</p></div><label><span>Building and floor</span><select><option>Summerlin Campus · First floor</option></select></label></div><div className="facilities-floor-layout"><div className="facilities-floor-map" role="group" aria-label="Interactive schematic floor plan">{facilitiesRooms.map((item) => <button key={item.id} type="button" className={item.id === selectedId ? "selected" : ""} style={{ left: `${item.x}%`, top: `${item.y}%`, width: `${item.width}%`, height: `${item.height}%` }} onClick={() => setSelectedId(item.id)}><strong>{item.name}</strong><small>{state.requests.some((request) => request.location === item.name && request.status !== "complete") ? "Open work" : state.reservations.some((reservation) => reservation.roomId === item.id && reservation.status === "approved") ? "Reserved" : item.type}</small></button>)}</div><aside className="facilities-panel facilities-room-card"><span className="facilities-rule-chip">{room.type}</span><h2>{room.name}</h2><p>{room.building} · {room.floor}</p><dl className="facilities-detail-list"><div><dt>Capacity</dt><dd>{room.capacity}</dd></div><div><dt>Open work</dt><dd>{work.filter((item) => item.status !== "complete").length}</dd></div><div><dt>Reservations</dt><dd>{reservations.length}</dd></div></dl>{work.map((item) => <p className="facilities-linked-record" key={item.id}><strong>{item.id}</strong> · {item.title}</p>)}{reservations.slice(0, 2).map((item) => <p className="facilities-linked-record" key={item.id}><strong>{item.date}</strong> · {item.title}</p>)}</aside></div></section>;
}

function ReportsView({ state, setState }: { state: FacilitiesDemoState; setState: React.Dispatch<React.SetStateAction<FacilitiesDemoState>> }) {
  const [report, setReport] = useState("work-orders"); const [organization, setOrganization] = useState("All organizations"); const [location, setLocation] = useState("All locations"); const [message, setMessage] = useState(""); const importRef = useRef<HTMLInputElement>(null);
  const exportWorkbook = async () => { const { default: ExcelJS } = await import("exceljs"); const workbook = new ExcelJS.Workbook(); workbook.creator = "Facilities Dashboard Demo"; const add = (name: string, rows: Array<Record<string, unknown>>) => { const sheet = workbook.addWorksheet(name); const keys = Object.keys(rows[0] || { message: "No records" }); sheet.columns = keys.map((key) => ({ header: key.replaceAll(/([A-Z])/g, " $1").replace(/^./, (letter) => letter.toUpperCase()), key, width: 22 })); rows.forEach((row) => sheet.addRow(row)); sheet.getRow(1).font = { bold: true }; sheet.autoFilter = { from: "A1", to: `${String.fromCharCode(64 + keys.length)}1` }; }; add("Work Orders", state.requests); add("Reservations", state.reservations); add("Inventory", state.stock); add("Custody", state.custody); const bytes = await workbook.xlsx.writeBuffer(); const blob = new Blob([bytes], { type: "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" }); const url = URL.createObjectURL(blob); const anchor = document.createElement("a"); anchor.href = url; anchor.download = "facilities-operations-report.xlsx"; anchor.click(); URL.revokeObjectURL(url); setMessage("Excel report exported with four worksheets."); };
  const importInventory = async (file?: File) => { if (!file) return; try { let rows: Array<Record<string, unknown>> = []; if (file.name.toLowerCase().endsWith(".xlsx")) { const { default: ExcelJS } = await import("exceljs"); const workbook = new ExcelJS.Workbook(); await workbook.xlsx.load(await file.arrayBuffer()); const sheet = workbook.worksheets[0]; const headers = (sheet.getRow(1).values as unknown[]).slice(1).map((value) => String(value).trim().toLowerCase().replaceAll(" ", "")); sheet.eachRow((row, index) => { if (index === 1) return; const values = (row.values as unknown[]).slice(1); rows.push(Object.fromEntries(headers.map((header, column) => [header, values[column]]))); }); } else { const lines = (await file.text()).split(/\r?\n/).filter(Boolean); const headers = lines[0].split(",").map((value) => value.trim().toLowerCase().replaceAll(" ", "")); rows = lines.slice(1).map((line) => Object.fromEntries(line.split(",").map((value, index) => [headers[index], value.trim()]))); } const accepted = rows.filter((row) => row.name && row.sku).map((row, index): FacilitiesStockItem => ({ id: `imported-${Date.now()}-${index}`, name: String(row.name), sku: String(row.sku), category: String(row.category || "Imported"), onHand: Number(row.onhand || 0), reorderPoint: Number(row.reorderpoint || 0), target: Number(row.target || row.onhand || 0), unit: String(row.unit || "each"), location: String(row.location || "Warehouse B"), averageWeeklyUse: Number(row.averageweeklyuse || 0), lastCounted: "2026-09-15" })); if (!accepted.length) throw new Error("No rows included both Name and SKU columns."); setState((current) => ({ ...current, stock: [...accepted, ...current.stock.filter((item) => !accepted.some((next) => next.sku === item.sku))] })); setMessage(`${accepted.length} inventory row${accepted.length === 1 ? "" : "s"} imported into this browser-only demo.`); } catch (error) { setMessage(error instanceof Error ? error.message : "The file could not be imported."); } finally { if (importRef.current) importRef.current.value = ""; } };
  const eventTypes = state.reservations.reduce<Record<string, number>>((result, item) => ({ ...result, [item.eventType]: (result[item.eventType] || 0) + 1 }), {}); const max = Math.max(...Object.values(eventTypes), 1);
  return <section className="facilities-page"><div className="facilities-page-heading"><div><p className="kicker">Reports and Excel</p><h1>Turn activity into purchasing and planning decisions.</h1><p>Every chart is tied to the same work, reservation, location, and inventory records.</p></div><div><label className="secondary-button facilities-file-button">Import inventory<input ref={importRef} type="file" accept=".xlsx,.csv" onChange={(event) => void importInventory(event.target.files?.[0])} /></label><button className="primary-button" onClick={() => void exportWorkbook()}>Export Excel report</button></div></div><p className="form-message" aria-live="polite">{message}</p><div className="facilities-report-filters"><label><span>Report</span><select value={report} onChange={(event) => setReport(event.target.value)}><option value="work-orders">Work orders</option><option value="events">Event types</option><option value="liquor">Liquor licenses</option><option value="inventory">Inventory usage</option><option value="hours">Hours and workload</option></select></label><label><span>Organization</span><select value={organization} onChange={(event) => setOrganization(event.target.value)}><option>All organizations</option>{[...new Set(state.reservations.map((item) => item.organization))].map((item) => <option key={item}>{item}</option>)}</select></label><label><span>Location</span><select value={location} onChange={(event) => setLocation(event.target.value)}><option>All locations</option>{facilitiesRooms.map((item) => <option key={item.id}>{item.name}</option>)}</select></label><label><span>Date range</span><select><option>Last 90 days</option><option>Current fiscal year</option><option>Custom range</option></select></label></div><div className="facilities-report-grid"><section className="facilities-panel"><header><div><p className="kicker">{report === "liquor" ? "License readiness" : report === "inventory" ? "Stock movement" : "Event mix"}</p><h2>{report === "liquor" ? "Alcohol-related reservations" : report === "inventory" ? "Most-used items" : "Reservations by event type"}</h2></div></header>{report === "liquor" ? <div className="facilities-mini-list">{state.reservations.filter((item) => item.alcohol).map((item) => <article key={item.id}><span><strong>{item.title}</strong><em>{item.date} · {item.organization}</em></span><span className={`status-chip status-chip--${item.liquorLicenseStatus === "received" ? "confirmed" : "declined"}`}>{formatStatus(item.liquorLicenseStatus)}</span></article>)}</div> : <div className="facilities-horizontal-chart">{(report === "inventory" ? state.stock.slice().sort((a, b) => b.averageWeeklyUse - a.averageWeeklyUse).slice(0, 5).map((item) => [item.name, item.averageWeeklyUse] as const) : Object.entries(eventTypes)).map(([label, value]) => <div key={label}><span>{label}</span><div><i style={{ width: `${Math.round(value / (report === "inventory" ? Math.max(...state.stock.map((item) => item.averageWeeklyUse), 1) : max) * 100)}%` }} /></div><strong>{value}</strong></div>)}</div>}</section><section className="facilities-panel"><header><div><p className="kicker">Operational recommendations</p><h2>Signals to act on</h2></div></header><div className="facilities-insight-list compact">{facilitiesInsights(state).map((item) => <article key={item.id} className={`facilities-insight facilities-insight--${item.level}`}><span /><div><strong>{item.title}</strong><p>{item.source}</p></div></article>)}</div></section></div></section>;
}

function CustomizeView({ state, setState }: { state: FacilitiesDemoState; setState: React.Dispatch<React.SetStateAction<FacilitiesDemoState>> }) {
  const labels: Record<string, string> = { priorities: "Smart priorities", workflow: "Live request workflow", usage: "Weekly usage patterns", activity: "Recent activity" };
  const move = (key: string, direction: -1 | 1) => setState((current) => { const sections = [...current.dashboardSections]; const index = sections.indexOf(key); const target = index + direction; if (target < 0 || target >= sections.length) return current; [sections[index], sections[target]] = [sections[target], sections[index]]; return { ...current, dashboardSections: sections }; });
  return <section className="facilities-page"><div className="facilities-page-heading"><div><p className="kicker">Customize dashboard</p><h1>Put the work you monitor first.</h1><p>Your layout is stored only in this browser for the synthetic demo.</p></div></div><section className="facilities-panel facilities-customize-list">{state.dashboardSections.map((key, index) => <article key={key}><label><input type="checkbox" checked={!state.hiddenDashboardSections.includes(key)} onChange={(event) => setState((current) => ({ ...current, hiddenDashboardSections: event.target.checked ? current.hiddenDashboardSections.filter((item) => item !== key) : [...current.hiddenDashboardSections, key] }))} /><span><strong>{labels[key]}</strong><small>{eventDescription(key)}</small></span></label><div><button aria-label={`Move ${labels[key]} up`} disabled={index === 0} onClick={() => move(key, -1)}>↑</button><button aria-label={`Move ${labels[key]} down`} disabled={index === state.dashboardSections.length - 1} onClick={() => move(key, 1)}>↓</button></div></article>)}</section></section>;
}

function eventDescription(key: string) { return key === "priorities" ? "Urgent work, low stock, licenses, and usage signals" : key === "workflow" ? "Requests across approval, preparation, and active work" : key === "usage" ? "Typical weekly stock and equipment movement" : "Recent changes across facilities operations"; }

function FacilitiesWorkspace({ api, context, memberships, previewMode, previewPersona, setPreviewPersona, signOut }: { api: PilotApiClient; context: AuthorizationContext; memberships: ExperienceMembership[]; previewMode: boolean; previewPersona: SyntheticPersonaKey | null; setPreviewPersona: (persona: SyntheticPersonaKey) => void; signOut: () => Promise<void> }) {
  const admin = previewPersona !== "facilities_requester";
  const [state, setState] = useState<FacilitiesDemoState>(cloneFacilitiesDemoState()); const [ready, setReady] = useState(false); const [view, setView] = useState<FacilitiesView>("home"); const [selectedRequest, setSelectedRequest] = useState<FacilitiesRequest | null>(null);
  useEffect(() => { setState(loadState()); setReady(true); }, []);
  useEffect(() => { if (ready) window.localStorage.setItem(stateKey, JSON.stringify(state)); }, [ready, state]);
  useEffect(() => { setView("home"); setSelectedRequest(null); }, [previewPersona]);
  const reset = () => { const next = cloneFacilitiesDemoState(); setState(next); window.localStorage.setItem(stateKey, JSON.stringify(next)); setView("home"); setSelectedRequest(null); };
  const navigate = (next: FacilitiesView) => { setSelectedRequest(null); setView(next); };
  let content: React.ReactNode;
  if (selectedRequest) content = <RequestDetail request={selectedRequest} state={state} setState={setState} admin={admin} onBack={() => setSelectedRequest(null)} />;
  else if (view === "new-request") content = <RequestForm state={state} setState={setState} requester={context.displayName} onDone={setSelectedRequest} />;
  else if (view === "requests") content = <RequestsView state={state} setState={setState} admin={admin} requester={context.displayName} onOpen={setSelectedRequest} onNew={() => navigate("new-request")} />;
  else if (view === "spaces") content = <SpacesView state={state} setState={setState} admin={admin} requester={context.displayName} />;
  else if (view === "warehouse" && admin) content = <WarehouseView state={state} setState={setState} />;
  else if (view === "supplies") content = <SuppliesView state={state} setState={setState} admin={admin} requester={context.displayName} onOpen={setSelectedRequest} />;
  else if (view === "directory") content = <DirectoryView />;
  else if (view === "reports" && admin) content = <ReportsView state={state} setState={setState} />;
  else if (view === "floor-plans" && admin) content = <FloorPlanView state={state} />;
  else if (view === "customize" && admin) content = <CustomizeView state={state} setState={setState} />;
  else content = admin ? <AdminHome state={state} onNavigate={navigate} onOpen={setSelectedRequest} /> : <RequesterHome state={state} onNavigate={navigate} onOpen={setSelectedRequest} requester={context.displayName} />;
  const visibleNav = navItems.filter((item) => admin || !item.adminOnly);
  return <div className="navigate-platform facilities-shell"><CreatorPreviewBanner persona={previewPersona} onPersona={setPreviewPersona} onExit={() => void signOut()} scope="facilities" tutorialWorkspace="facilities" /><FacilitiesHeader api={api} memberships={memberships} context={context} previewMode={previewMode} signOut={signOut} /><div className="facilities-app"><aside className="facilities-sidebar"><nav aria-label="Facilities workspace">{visibleNav.map((item) => <button key={item.key} className={view === item.key && !selectedRequest ? "active" : ""} onClick={() => navigate(item.key)}><FacilitiesIcon name={item.key} /><span>{item.label}</span>{item.key === "requests" && admin ? <b>{state.requests.filter((request) => request.status === "approval").length}</b> : null}</button>)}</nav><div><button className="facilities-reset" onClick={reset}>Reset synthetic data</button><small>Changes stay in this browser only.</small></div></aside><main className="facilities-main">{content}</main></div></div>;
}

export function FacilitiesDashboardApp() {
  return <PlatformAccess experience="facilities">{({ api, context, memberships, previewMode, previewScope, previewPersona, setPreviewPersona, signOut }) => {
    const requestedRole = typeof window === "undefined" ? null : facilitiesDemoPersonaForSlug(new URLSearchParams(window.location.search).get("demo"));
    if (previewMode && previewScope === "facilities" && !requestedRole) return <FacilitiesRoleChooser persona={previewPersona || "facilities_administrator"} onPersona={setPreviewPersona} signOut={signOut} />;
    return <FacilitiesWorkspace key={previewPersona || context.userId} api={api} context={context} memberships={memberships} previewMode={previewMode} previewPersona={previewPersona} setPreviewPersona={setPreviewPersona} signOut={signOut} />;
  }}</PlatformAccess>;
}
